import{_ as e,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"16 | 再回首：JdbcTemplate章节小结","description":"","frontmatter":{},"headers":[{"level":3,"title":"JdbcTemplate 重点回顾","slug":"jdbctemplate-重点回顾","link":"#jdbctemplate-重点回顾","children":[]},{"level":3,"title":"13｜JDBC 访问框架：如何抽取 JDBC 模板并隔离数据库？","slug":"_13-jdbc-访问框架-如何抽取-jdbc-模板并隔离数据库","link":"#_13-jdbc-访问框架-如何抽取-jdbc-模板并隔离数据库","children":[]},{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":3,"title":"参考答案","slug":"参考答案","link":"#参考答案","children":[]},{"level":3,"title":"14｜增强模板：如何抽取专门的部件完成专门的任务？","slug":"_14-增强模板-如何抽取专门的部件完成专门的任务","link":"#_14-增强模板-如何抽取专门的部件完成专门的任务","children":[]},{"level":3,"title":"思考题","slug":"思考题-1","link":"#思考题-1","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-1","link":"#参考答案-1","children":[]},{"level":3,"title":"15｜mBatis : 如何将 SQL 语句配置化？","slug":"_15-mbatis-如何将-sql-语句配置化","link":"#_15-mbatis-如何将-sql-语句配置化","children":[]},{"level":3,"title":"思考题","slug":"思考题-2","link":"#思考题-2","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-2","link":"#参考答案-2","children":[]}],"relativePath":"手把手带你写一个MiniSpring/16｜再回首：JdbcTemplate章节小结.md","filePath":"手把手带你写一个MiniSpring/16｜再回首：JdbcTemplate章节小结.md","lastUpdated":1795557483000}'),l={name:"手把手带你写一个MiniSpring/16｜再回首：JdbcTemplate章节小结.md"};function p(i,a,c,d,r,o){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_16-再回首-jdbctemplate章节小结" tabindex="-1">16 | 再回首：JdbcTemplate章节小结 <a class="header-anchor" href="#_16-再回首-jdbctemplate章节小结" aria-label="Permalink to &quot;16 | 再回首：JdbcTemplate章节小结&quot;">​</a></h1><p>你好，我是郭屹。</p><p>恭喜你学完了 MiniSpring 的第三部分——JdbcTemplate 了。JdbcTemplate 在 Spring 框架里，扮演着非常重要的角色。通过它，我们可以更加便捷地进行数据库操作，缩短了开发周期和开发成本，同时也降低了出错的风险。</p><p>它对 Spring 应用程序的稳定性和性能表现有着至关重要的影响，已经成为开发高效、高质量应用程序的不可或缺的一部分。</p><p>为了让你更好地掌握这部分内容，下面我们对这一整章做一个重点回顾。</p><h3 id="jdbctemplate-重点回顾" tabindex="-1">JdbcTemplate 重点回顾 <a class="header-anchor" href="#jdbctemplate-重点回顾" aria-label="Permalink to &quot;JdbcTemplate 重点回顾&quot;">​</a></h3><p>JdbcTemplate 是 Spring 框架中的一部分，是 Spring 对数据访问的一个实现，在 Spring 应用程序中被广泛采用。它这个实现特别好地体现了 Rod Johnson 对简洁实用的原则的把握。JdbcTemplate 封装了 JDBC 的 API，并提供了更为便捷的访问方式，使得开发人员在不需要编写大量代码的情况下，能够高效、灵活地进行数据库操作。</p><p>我们知道，JDBC 的程序都是类似的，所以这个部分我们提取出一个 JDBC 访问的模板，同时引入 DataSource 概念，屏蔽具体的数据库，就便利了上层应用业务程序员。然后，我们再进行 SQL 参数的处理，SQL 请求带有参数，实现把数据转换成 SQL 语句所需要的参数格式，对 SQL 语句执行后的返回结果，又要自动绑定为业务对象。</p><p>之后，为了支持大量的数据访问，我们实现了数据库连接池提高性能，并且把连接池构造变成一个 Bean 注入到 IoC 容器里，还可以让用户自行配置连接池的参数。最后，进一步把程序里的 SQL 语句也抽取出来，配置到外部文件中，实现一个简单的 MyBatis。</p><p>这就是这一章实现 JdbcTemplate 的过程，你可以再回顾一下。另外我们每一节课后面都给了一道思考题，让你在我们实现的这个极简框架上进行扩展，如果你认真学习了这一章的内容，相信你是可以举一反三的，自己提出解决方案。</p><p>方法可能不同，但目标是一样的。我把参考答案写在文稿中了，你可以看一下，如果你有更好的思路和想法，也欢迎和我分享。下节课我们马上要进入 AOP 的环节了，一起期待一下吧！</p><h3 id="_13-jdbc-访问框架-如何抽取-jdbc-模板并隔离数据库" tabindex="-1">13｜JDBC 访问框架：如何抽取 JDBC 模板并隔离数据库？ <a class="header-anchor" href="#_13-jdbc-访问框架-如何抽取-jdbc-模板并隔离数据库" aria-label="Permalink to &quot;13｜JDBC 访问框架：如何抽取 JDBC 模板并隔离数据库？&quot;">​</a></h3><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们现在只实现了 query，想一想如果想要实现 update 应该如何做呢？</p><h3 id="参考答案" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>我们现在 JdbcTemplate 类的结构，对于 query() 和 update() 是并列设计的，只要在类中对应的提供一个方法，形如：int update(String sql, Object[] args, int[] argTypes)。这个方法内部是一个 PreparedStatement，SQL 是要执行的 SQL 语句，args 是 SQL 参数，argTypes 是数据类型，返回值是受影响的行数。</p><h3 id="_14-增强模板-如何抽取专门的部件完成专门的任务" tabindex="-1">14｜增强模板：如何抽取专门的部件完成专门的任务？ <a class="header-anchor" href="#_14-增强模板-如何抽取专门的部件完成专门的任务" aria-label="Permalink to &quot;14｜增强模板：如何抽取专门的部件完成专门的任务？&quot;">​</a></h3><h3 id="思考题-1" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-1" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>你想一想我们应该怎么改造数据库连接池，保证多线程安全？</p><h3 id="参考答案-1" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-1" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>这个问题有不同的方案，下面是一种思路供参考。</p><p>提供两个队列，一个用于忙的连接，一个用于空闲连接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   private BlockingQueue&lt;​PooledConnection&gt; busy;</span></span>
<span class="line"><span>   private BlockingQueue&lt;​PooledConnection&gt; idle;</span></span></code></pre></div><p>获取数据库连接就从 idle 队列中获取，程序大体如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (true) {</span></span>
<span class="line"><span>conn = idle.poll();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>就是死等一个空闲连接。然后加入忙队列。</p><p>当然，进一步考虑，还应当判断连接数是否到了最大，如果没有，则要先创建一个新的连接。创建的时候要小心了，因为是多线程的，所以要再次校验是否超过最大连接数，如使用 CAS技术：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (size.get() &lt; getPoolProperties().getMaxActive()) {</span></span>
<span class="line"><span>           if (size.addAndGet(1) &gt; getPoolProperties().getMaxActive()) {</span></span>
<span class="line"><span>               size.decrementAndGet();</span></span>
<span class="line"><span>           } else {</span></span>
<span class="line"><span>               return createConnection(now, con, username, password);</span></span>
<span class="line"><span>           }</span></span>
<span class="line"><span>       }</span></span></code></pre></div><p>而且还应当设置一个 timeout，如果在规定的时间内还没有拿到一个连接，就要抛出一个异常。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if ((System.currentTimeMillis() - now) &gt;= maxWait) {</span></span>
<span class="line"><span>               throw new PoolExhaustedException(</span></span>
<span class="line"><span>                   &quot;Timeout: Unable to fetch a connection in &quot; + (maxWait / 1000</span></span>
<span class="line"><span>                   &quot; seconds.&quot;);</span></span>
<span class="line"><span>       } else {</span></span>
<span class="line"><span>               continue;</span></span>
<span class="line"><span>       }</span></span></code></pre></div><p>关闭连接，也就是从 busy 队列移除，然后加入到 idle 队列中。</p><h3 id="_15-mbatis-如何将-sql-语句配置化" tabindex="-1">15｜mBatis : 如何将 SQL 语句配置化？ <a class="header-anchor" href="#_15-mbatis-如何将-sql-语句配置化" aria-label="Permalink to &quot;15｜mBatis : 如何将 SQL 语句配置化？&quot;">​</a></h3><h3 id="思考题-2" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-2" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们只是简单地实现了 select 语句的配置，如何扩展到 update 语句？进一步，如何实现读写分离？</p><h3 id="参考答案-2" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-2" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>我们可以在 sql 节点类 MapperNode 中增加一个属性 sqltype，表示 sql 语句的类型，比如 0表示 select，1 表示 update，2 表示 insert，3 表示 delete。这样我们就知道了一个 sql 语句是 read 还是 write。</p><p>然后 datasource 变成两个，一个是 readDatasource，一个是 writeDatasource，可以配置在外部文件中。JdbcTemplate 也提供一个 setDatasource() 允许动态设置数据源。</p><p>DefaultSqlSession 类中配置两个 data source，形如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> private DataSource readDataSource;</span></span>
<span class="line"><span> private DataSource writeDataSource;</span></span></code></pre></div><p>然后在 selectOne() 中这么判断：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> public Object selectOne(String sqlid, Object[] args, PreparedStatementCallback</span></span>
<span class="line"><span>   int sqltype = this.sqlSessionFactory.getMapperNode(sqlid).getSqlType();</span></span>
<span class="line"><span>if (sqltype==0)  {//read</span></span>
<span class="line"><span>jdbcTemplate.setDatasource(readDataSource);</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>   return jdbcTemplate.query(sql, args, pstmtcallback);</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>也就是说，每一次用 SqlSession 执行 SQL 语句的时候，都判断一下 SQL 类型，如果是read，则设置 readDatasource，否则设置 writeDatasource.</p>`,42)])])}const b=e(l,[["render",p]]);export{u as __pageData,b as default};
